/* The CV document renderer: templateHtml() builds every design from the
 * collected data, scaleCVToFit() fits the A4 page into the panel. */

import { photoData } from './app-state.js';

/* The official Europass logo (shared by the Europass + Scholar templates). */
const EP_LOGO='data:image/png;base64,';
/* The current Europass editor logo (white card + EU flag + wordmark),
   extracted from the reference CV — used by the Scholar template. */
const EP_LOGO_MODERN='data:image/png;base64,';

export const A4_W=794;
export function scaleCVToFit(){
  const outer=document.getElementById('cvScaleOuter');
  const inner=document.getElementById('cvScaleInner');
  if(!outer||!inner)return;
  let availW;
  if(window.innerWidth<=900){
    const panelPad=Math.round(parseFloat(getComputedStyle(document.documentElement).fontSize)*0.5)*2;
    availW=window.innerWidth-panelPad;
  } else {
    const wrapper=outer.parentElement;
    availW=wrapper?wrapper.offsetWidth:outer.offsetWidth;
  }
  if(!availW||availW<10)return;
  const scale=availW/A4_W;
  outer.style.width=availW+'px';
  inner.style.transform=`scale(${scale})`;
  outer.style.height=Math.ceil(inner.offsetHeight*scale)+'px';
}
const _cvResizeObs=new ResizeObserver(scaleCVToFit);
document.addEventListener('DOMContentLoaded',()=>{
  const outer=document.getElementById('cvScaleOuter');
  if(outer)_cvResizeObs.observe(outer.parentElement||outer);
  scaleCVToFit();
});
window.addEventListener('resize',scaleCVToFit);

export function templateHtml(t,D){ /* D = collectPreviewData() — pure so the 3D gallery can render every design */
    const{name,title,email,phone,linkedin,location,cs,summary,skills,exp,edu,langs,interests,pubs,projs,vols,ph,esc,eH,dH,langLines,lH,pubH,projH,volH,skillList,contactLines,orderedContent}=D;
    let html='';
    switch(t){
        case'classic':html=`${photoData?`<div style="text-align:center;margin-bottom:2mm">${ph}</div>`:''}<div class="cv-name">${esc(name)}</div><div class="cv-title">${esc(title)}</div><div class="cv-contact">${esc(cs)}</div>${orderedContent}`;break;
        case'modern':html=`<div class="cv-header-modern"><div style="display:flex;align-items:center;gap:4mm">${ph}<div><div class="cv-name">${esc(name)}</div><div class="cv-title">${esc(title)}</div></div></div></div><div class="cv-body"><div class="cv-sidebar">${cs?`<div class="cv-section"><h2>Contact</h2><p>${esc(cs).replace(/\|/g,'<br>')}</p></div>`:''}${skills.trim()?`<div class="cv-section"><h2>Skills</h2><p>${esc(skills)}</p></div>`:''}${langLines?`<div class="cv-section"><h2>Languages</h2>${langLines}</div>`:''}</div><div class="cv-main">${summary.trim()?`<div class="cv-section"><h2>Summary</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section"><h2>Education</h2>${dH}</div>`:''}</div></div>`;break;
        case'tabular':html=`<div style="display:flex;align-items:center;gap:4mm;justify-content:center;margin-bottom:2mm">${ph}<div><div class="cv-name" style="margin:0">${esc(name)}</div><div style="font-size:9pt;color:#555">${esc(title)}</div></div></div><div style="text-align:center;margin-bottom:3mm;font-size:8pt;color:#666">${esc(cs)}</div>${summary.trim()?`<p style="margin-bottom:2.5mm;font-style:italic">${esc(summary)}</p>`:''}${exp.length?`<table><tr><th colspan="3">Experience</th></tr>${exp.map(e=>`<tr><td><strong>${esc(e.title)}</strong><br>${esc(e.description)}</td><td>${esc(e.company)}</td><td>${esc(e.dates)}</td></tr>`).join('')}</table>`:''}${edu.length?`<table><tr><th colspan="3">Education</th></tr>${edu.map(e=>`<tr><td>${esc(e.degree)}</td><td>${esc(e.institution)}</td><td>${esc(e.year)}</td></tr>`).join('')}</table>`:''}${langLines?`<table><tr><th>Languages</th></tr><tr><td>${langLines.replace(/<div class="cv-lang-line">/g,'<div>').replace(/<span class="lvl">/g,'<span style="color:#666">')}</td></tr></table>`:''}${skills.trim()?`<table><tr><th>Skills</th></tr><tr><td>${esc(skills)}</td></tr></table>`:''}`;break;
        case'sidebar-bold':html=`<div class="cv-sidebar-left">${ph?`<div style="text-align:center;margin-bottom:3mm">${ph}</div>`:''}<div style="font-family:var(--cv-font-heading);font-size:16pt;font-weight:800;line-height:1.2;margin-bottom:1.5mm">${esc(name)}</div>${title?`<div style="font-size:8.5pt;opacity:0.85;margin-bottom:4mm">${esc(title)}</div>`:''}${cs?`<div style="border-top:1.5px solid rgba(255,255,255,0.4);padding-top:3mm;margin-bottom:3mm"><div style="font-size:7.5pt;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:2mm;opacity:0.7">Contact</div>${cs.split('|').map(c=>`<div style="font-size:7.5pt;margin-bottom:1mm;word-break:break-all">${esc(c.trim())}</div>`).join('')}</div>`:''}${skills.trim()?`<div style="border-top:1.5px solid rgba(255,255,255,0.4);padding-top:3mm;margin-bottom:3mm"><div style="font-size:7.5pt;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:2mm;opacity:0.7">Skills</div>${skillList.map(s=>`<div style="font-size:7pt;background:rgba(255,255,255,0.18);border-radius:2mm;padding:0.8mm 2mm;margin-bottom:1mm;display:inline-block;margin-right:1mm">${esc(s)}</div>`).join('')}</div>`:''}${langLines?`<div style="border-top:1.5px solid rgba(255,255,255,0.4);padding-top:3mm"><div style="font-size:7.5pt;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:2mm;opacity:0.7">Languages</div>${langs.map(l=>`<div style="font-size:7.5pt;margin-bottom:1mm">${esc(l.language)}${l.level?` <span style="opacity:0.75">· ${esc(l.level)}</span>`:''}</div>`).join('')}</div>`:''}</div><div class="cv-main-right">${summary.trim()?`<div class="cv-section"><h2>Professional Summary</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section"><h2>Education</h2>${dH}</div>`:''}</div>`;break;
        case'minimal':html=`${ph?`<div style="text-align:center;margin-bottom:3mm">${ph}</div>`:''}<div class="cv-name">${esc(name)}</div>${title?`<div class="cv-title">${esc(title)}</div>`:''}<div style="text-align:center;font-size:7.5pt;color:#888;margin-bottom:4mm">${esc(cs)}</div><div style="border-top:0.5px solid #ccc;margin-bottom:4mm"></div>${orderedContent}`;break;
        case'colorful':html=`<div class="cv-header-colorful"><div style="display:flex;align-items:center;gap:4mm">${ph}<div><div class="cv-name" style="color:white">${esc(name)}</div><div style="font-size:10pt;opacity:0.9">${esc(title)}</div><div style="font-size:7.5pt;opacity:0.8;margin-top:1mm">${esc(cs)}</div></div></div></div><div class="cv-body"><div class="cv-sidebar">${skills.trim()?`<div class="cv-section"><h2>Skills</h2><p>${esc(skills)}</p></div>`:''}${langLines?`<div class="cv-section"><h2>Languages</h2>${langLines}</div>`:''}</div><div class="cv-main">${summary.trim()?`<div class="cv-section"><h2>Summary</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section"><h2>Education</h2>${dH}</div>`:''}</div></div>`;break;
        case'executive':html=`${ph?`<div style="text-align:center;margin-bottom:3mm">${ph}</div>`:''}<div style="border-bottom:3px double var(--cv-color);padding-bottom:3mm;margin-bottom:4mm;text-align:center"><div class="cv-name">${esc(name)}</div>${title?`<div style="font-size:9pt;color:var(--cv-color);letter-spacing:0.06em;margin-top:1mm">${esc(title)}</div>`:''}<div style="font-size:7.5pt;color:#666;margin-top:1.5mm">${esc(cs)}</div></div>${orderedContent}`;break;
        case'timeline':html=`${ph?`<div style="text-align:center;margin-bottom:2mm">${ph}</div>`:''}<div class="cv-name">${esc(name)}</div>${title?`<div style="text-align:center;font-size:9pt;color:var(--cv-color);margin-bottom:1mm">${esc(title)}</div>`:''}<div style="text-align:center;font-size:7.5pt;color:#888;margin-bottom:4mm">${esc(cs)}</div>${summary.trim()?`<div class="cv-section"><h2>Summary</h2><p>${esc(summary)}</p></div>`:''}${skills.trim()?`<div class="cv-section"><h2>Skills</h2><p>${esc(skills)}</p></div>`:''}${langLines?`<div class="cv-section"><h2>Languages</h2>${langLines}</div>`:''}${exp.length?`<div class="cv-section"><h2>Experience</h2><div class="timeline-line">${exp.map(e=>`<div class="timeline-item"><div class="cv-item-header"><span><strong>${esc(e.title)}</strong> — ${esc(e.company)}</span><span>${esc(e.dates)}</span></div><p>${esc(e.description)}</p></div>`).join('')}</div></div>`:''}${edu.length?`<div class="cv-section"><h2>Education</h2><div class="timeline-line">${edu.map(e=>`<div class="timeline-item"><div class="cv-item-header"><span><strong>${esc(e.degree)}</strong> — ${esc(e.institution)}</span><span>${esc(e.year)}</span></div></div>`).join('')}</div></div>`:''}`;break;
        case'newspaper':html=`${ph?`<div style="column-span:all;text-align:center;margin-bottom:2mm">${ph}</div>`:''}<div class="cv-name">${esc(name)}</div><div style="text-align:center;column-span:all;font-size:8pt;border-bottom:2px solid var(--cv-color);margin-bottom:3mm;padding-bottom:1.5mm;color:#666">${esc(title)}${cs?' | '+esc(cs):''}</div>${summary.trim()?`<div class="cv-section"><h2>Summary</h2><p>${esc(summary)}</p></div>`:''}${skills.trim()?`<div class="cv-section"><h2>Skills</h2><p>${esc(skills)}</p></div>`:''}${langLines?`<div class="cv-section"><h2>Languages</h2>${langLines}</div>`:''}${exp.length?`<div class="cv-section"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section"><h2>Education</h2>${dH}</div>`:''}`;break;
        case'magazine':html=`<div style="background:var(--cv-color);color:white;padding:8mm 12mm;margin:-14mm -12mm 5mm;text-align:center"><div class="cv-name" style="color:white;font-size:24pt">${esc(name)}</div>${title?`<div style="font-size:10pt;opacity:0.85;font-style:italic;margin-top:1mm">${esc(title)}</div>`:''}</div>${ph?`<div style="text-align:center;margin-bottom:3mm">${ph}</div>`:''}<div style="text-align:center;font-size:7.5pt;color:#888;margin-bottom:4mm;border-bottom:1px solid #eee;padding-bottom:3mm">${esc(cs)}</div>${orderedContent}`;break;
        case'infographic':html=`<div style="display:flex;align-items:center;gap:4mm;margin-bottom:4mm;padding-bottom:3mm;border-bottom:2px solid var(--cv-color)">${ph}<div><div class="cv-name">${esc(name)}</div>${title?`<div style="font-size:9pt;color:var(--cv-color)">${esc(title)}</div>`:''}</div></div><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:1.5mm;margin-bottom:3mm">${[email,phone,linkedin,location].filter(Boolean).map(c=>`<div class="info-card" style="font-size:7pt">${esc(c)}</div>`).join('')}</div>${summary.trim()?`<div class="info-card"><strong>Summary</strong><p style="margin-top:1mm">${esc(summary)}</p></div>`:''}${langLines?`<div class="info-card" style="margin-top:1.5mm"><strong>Languages</strong><div style="margin-top:1mm">${langs.map(l=>`<span style="display:inline-block;background:var(--cv-color);color:white;border-radius:2mm;padding:0.5mm 2mm;font-size:7pt;margin:0.4mm">${esc(l.language)}${l.level?' · '+esc(l.level):''}</span>`).join('')}</div></div>`:''}<div style="display:grid;grid-template-columns:${exp.length&&edu.length?'3fr 2fr':'1fr'};gap:3mm;margin-top:2mm">${exp.length?`<div><div class="cv-section"><h2>Experience</h2>${eH}</div></div>`:''}${edu.length?`<div><div class="cv-section"><h2>Education</h2>${dH}</div>${skills.trim()?`<div class="cv-section"><h2>Skills</h2><p>${esc(skills)}</p></div>`:''}</div>`:''}</div>${!edu.length&&skills.trim()?`<div class="cv-section"><h2>Skills</h2><p>${esc(skills)}</p></div>`:''}`;break;
        case'creative':html=`<div style="text-align:center;padding-bottom:4mm;margin-bottom:4mm;border-bottom:3px solid var(--cv-color)">${ph?`<div style="margin-bottom:2mm">${ph}</div>`:''}<div class="cv-name">${esc(name)}</div>${title?`<div style="font-size:9.5pt;color:var(--cv-color);font-weight:600;margin-top:1mm">${esc(title)}</div>`:''}<div style="font-size:7.5pt;color:#888;margin-top:2mm">${[email,phone,linkedin,location].filter(Boolean).map(c=>`<span style="display:inline-block;background:#f1f5f9;border-radius:3mm;padding:0.5mm 2.5mm;margin:0.5mm">${esc(c)}</span>`).join('')}</div></div>${summary.trim()?`<div class="cv-section"><h2>Summary</h2><p>${esc(summary)}</p></div>`:''}${skills.trim()?`<div class="cv-section"><h2>Skills</h2><div style="display:flex;flex-wrap:wrap;gap:1.5mm">${skillList.map(s=>`<span style="background:var(--cv-color);color:white;border-radius:3mm;padding:0.8mm 2.5mm;font-size:7pt;font-weight:600">${esc(s)}</span>`).join('')}</div></div>`:''}${langLines?`<div class="cv-section"><h2>Languages</h2>${langs.map(l=>`<span style="display:inline-block;border:1px solid var(--cv-color);color:var(--cv-color);border-radius:3mm;padding:0.6mm 2.5mm;font-size:7pt;font-weight:600;margin:0.4mm">${esc(l.language)}${l.level?' · '+esc(l.level):''}</span>`).join('')}</div>`:''}${exp.length?`<div class="cv-section"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section"><h2>Education</h2>${dH}</div>`:''}`;break;
        case'corporate':html=`<div style="background:#1a3a5c;color:white;padding:6mm 8mm;margin:-9mm -9mm 5mm;display:flex;align-items:center;gap:4mm">${ph}<div><div class="cv-name" style="color:white;font-size:18pt">${esc(name)}</div>${title?`<div style="font-size:9pt;opacity:0.85;margin-top:0.5mm">${esc(title)}</div>`:''}<div style="font-size:7.5pt;opacity:0.7;margin-top:1.5mm">${esc(cs)}</div></div></div>${orderedContent}`;break;
        case'nordic':html=`<div class="cv-head"><div style="min-width:0">${ph?`<div style="margin-bottom:2.5mm">${ph}</div>`:''}<div class="cv-name">${esc(name)}</div>${title?`<div class="cv-title">${esc(title)}</div>`:''}</div>${contactLines?`<div class="cv-head-contact">${contactLines}</div>`:''}</div><div class="cv-body"><div class="cv-main">${summary.trim()?`<div class="cv-section"><h2>Profile</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section"><h2>Education</h2>${dH}</div>`:''}</div><aside class="cv-aside">${skillList.length?`<div class="cv-section"><h2>Skills</h2><ul class="cv-skill-list">${skillList.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>`:''}${langLines?`<div class="cv-section"><h2>Languages</h2>${langLines}</div>`:''}</aside></div>`;break;
        case'swiss':html=`<div class="cv-toprule"></div><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:5mm"><div style="min-width:0"><div class="cv-name">${esc(name)}</div>${title?`<div class="cv-title">${esc(title)}</div>`:''}<div class="cv-contact-line">${esc(cs)}</div></div>${ph?`<div style="flex-shrink:0">${ph}</div>`:''}</div><div class="cv-body"><aside class="cv-side">${skillList.length?`<div class="cv-section"><h2>Skills</h2><ul class="cv-skill-list">${skillList.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>`:''}${langLines?`<div class="cv-section"><h2>Languages</h2>${langLines}</div>`:''}</aside><div class="cv-main">${summary.trim()?`<div class="cv-section"><h2>Profile</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section"><h2>Education</h2>${dH}</div>`:''}</div></div>`;break;
        case'academic':html=`${ph?`<div style="text-align:center;margin-bottom:2mm">${ph}</div>`:''}<div class="cv-name">${esc(name)}</div><div class="cv-contact">${esc(title)}${cs?' · '+esc(cs):''}</div>${orderedContent}`;break;
        case'compact':html=`<div class="cv-head">${ph}<div style="min-width:0"><div class="cv-name">${esc(name)}</div>${title?`<div class="cv-title">${esc(title)}</div>`:''}</div>${contactLines?`<div class="cv-head-contact">${contactLines}</div>`:''}</div>${summary.trim()?`<div class="cv-section"><h2>Profile</h2><p>${esc(summary)}</p></div>`:''}<div class="cv-cols"><div class="cv-col-a">${exp.length?`<div class="cv-section"><h2>Experience</h2>${eH}</div>`:''}</div><div class="cv-col-b">${edu.length?`<div class="cv-section"><h2>Education</h2>${dH}</div>`:''}${skillList.length?`<div class="cv-section"><h2>Skills</h2><p style="font-size:8pt">${esc(skills)}</p></div>`:''}${langLines?`<div class="cv-section"><h2>Languages</h2>${langLines}</div>`:''}</div></div>`;break;
        case'europass':{
            /* Faithful reproduction of the official Europass CV (classic DOCX template)
               issued by the European Commission. Verified 2026-11 against the official
               template currently distributed by EU institutions (europa.eu / EEAS
               "standard_cv.docx"): the footer genuinely reads "© European Union, 2002-2015 |
               europass.cedefop.europa.eu" — that copyright range is the EU's own notice for
               the CURRENT template revision (last revised 2015, which added the Digital
               competence self-assessment grid and EQF levels); it is not an outdated copy.
               Styling from the official DOCX: Arial · logo header · right-aligned labels in
               a 50mm gutter · navy #0E4194 caps headings with #2E90CB rules · #1593CB field
               labels · CEFR grid. Section order and the "Personal skills" sub-labels
               (Communication / Organisational-managerial / Job-related / Digital
               competence) follow the official document; sections without collected data
               (Sex-DoB-Nationality, Additional information, Annexes) are omitted per the
               template's own "Remove any empty headings" rule. */
            const epLvl=l=>{const v=(l.level||'').trim();return v?v.toUpperCase():'—';};
            const isNative=l=>['native','mother tongue','nativ'].includes((l.level||'').toLowerCase().trim());
            const motherTongues=langs.filter(isNative),otherLangs=langs.filter(l=>!isNative(l));
            /* Route free-text skills into the official "Personal skills" sub-labels
               (order per official template: Communication → Organisational/managerial →
               Job-related → Digital competence). Digital-first so e.g. "CMS" or "Content
               management" never lands under managerial. */
            const epKw={
                dig:/\b(microsoft|office|excel|word|powerpoint|outlook|python|java(?:script)?|typescript|sql|nosql|html|css|react|vue|angular|node(?:\.js)?|git|github|gitlab|docker|kubernetes|aws|azure|gcp|linux|macos|windows|matlab|\br\b|photoshop|illustrator|figma|canva|adobe|autocad|autodesk|solidworks|revit|\bcad\b|\bbim\b|tableau|power\s+bi|salesforce|\bsap\b|wordpress|shopify|\bseo\b|\bsem\b|\bcrm\b|\berp\b|\bcms\b|php|laravel|django|flask|c\+\+|c#|\.net|swift|kotlin|android|\bios\b|data\s+analy\w+|pandas|numpy|spark|hadoop|machine\s+learning|deep\s+learning|artificial\s+intelligence|\bai\b|prompt\s+engineering|video\s+editing|photo\s+editing|spreadsheet|database|web\s+development|software\s+development|programming|coding|devops|ci\/cd|jira|confluence|slack|trello|notion|zapier|hubspot|google\s+analytics|\bgis\b|vmware|\bict\b|computer)\b/i,
                comm:/\b(communicat\w*|presentation\w*|public\s+speaking|negotiat\w*|interpersonal|teamwork|team\s+player|collaborat\w*|stakeholder\w*|storytelling|persuasion|mediation|facilitat\w*|active\s+listening|customer\s+service)\b/i,
                org:/\b(organiz\w*|organis\w*|leadership|leading|management|managing|planning|coordinat\w*|delegation|mentoring|coaching|strategic\s+thinking|logistics|administration)\b/i};
            const epB={comm:[],org:[],job:[],dig:[]};
            skillList.forEach(s=>{const x=s.toLowerCase();if(epKw.dig.test(x))epB.dig.push(s);else if(epKw.comm.test(x))epB.comm.push(s);else if(epKw.org.test(x))epB.org.push(s);else epB.job.push(s);});
            const epSkillRow=(label,items)=>items.length?`<div class="ep-row"><div class="ep-k">${label}</div><div class="ep-v">${items.map(esc).join('; ')}</div></div>`:'';
            const epIcon={
                pin:'<svg viewBox="0 0 24 24" fill="none" stroke="#1593cb" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 12-9 12s-9-5-9-12a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>',
                phone:'<svg viewBox="0 0 24 24" fill="none" stroke="#1593cb" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.13.96.36 1.9.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.91.34 1.85.57 2.81.7A2 2 0 0 1 22 16.92z"/></svg>',
                mail:'<svg viewBox="0 0 24 24" fill="none" stroke="#1593cb" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m22 7-10 6L2 7"/></svg>',
                web:'<svg viewBox="0 0 24 24" fill="none" stroke="#1593cb" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M2 12h20"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>'};
            const contacts=[location?{i:'pin',t:esc(location)}:null,phone?{i:'phone',t:esc(phone)}:null,email?{i:'mail',t:`<a href="mailto:${esc(email)}">${esc(email)}</a>`}:null,linkedin?{i:'web',t:`<a href="${esc(linkedin)}" target="_blank" rel="noopener">${esc(linkedin)}</a>`}:null].filter(Boolean);
            const epSec=(label,rule)=>`<div class="ep-sec"><div class="ep-sec-label">${label}</div>${rule?'<div class="ep-rule"></div>':''}</div>`;
            const expEntry=e=>{
                const acts=(e.description||'').split('\n').map(s=>s.trim()).filter(Boolean);
                return `<div class="ep-row"><div class="ep-k ep-k-navy">${esc(e.dates)}</div><div class="ep-v"><div class="ep-occ">${esc(e.title)}</div>${e.company?`<div class="ep-org">${esc(e.company)}</div>`:''}</div></div>
                ${acts.length?`<div class="ep-row"><div class="ep-k"></div><div class="ep-v"><ul class="ep-ul">${acts.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div></div>`:''}`;
            };
            const eduEntry=e=>`<div class="ep-row"><div class="ep-k ep-k-navy">${esc(e.year)}</div><div class="ep-v"><div class="ep-occ">${esc(e.degree)}</div>${e.institution?`<div class="ep-org">${esc(e.institution)}</div>`:''}</div></div>`;
            html=`<div class="ep-header"><img class="ep-logo" src="${EP_LOGO}" alt="Europass"><div class="ep-hdr-mid">Curriculum Vitae</div><div class="ep-hdr-name">${esc(name)}</div></div>
            <div class="ep-sec ep-sec-first"><div class="ep-sec-label">Personal information</div></div>
            <div class="ep-pi"><div class="ep-gutter">${photoData?`<img class="ep-photo" src="${photoData}" alt="Profile photo">`:''}</div><div class="ep-pi-main"><div class="ep-name">${esc(name)}</div>${contacts.length?`<div class="ep-contact">${contacts.map(c=>`<div class="ep-ct">${epIcon[c.i]}<span>${c.t}</span></div>`).join('')}</div>`:''}</div></div>
            ${title||summary.trim()?`<div class="ep-sec"><div class="ep-sec-label">Job applied for<br>Position<br>Preferred job<br>Studies applied for<br><span class="ep-nocaps">personal statement</span></div><div class="ep-jaf">${title?`<div>${esc(title)}</div>`:''}${summary.trim()?`<div class="ep-ps">${esc(summary)}</div>`:''}</div></div>`:''}
            ${exp.length?epSec('Work experience',true)+exp.map(expEntry).join(''):''}
            ${edu.length?epSec('Education and training',true)+edu.map(eduEntry).join(''):''}
            ${langs.length||skills.trim()?epSec('Personal skills',true)+
                (motherTongues.length?`<div class="ep-row"><div class="ep-k">Mother tongue(s)</div><div class="ep-v">${motherTongues.map(l=>esc(l.language)).join(', ')}</div></div>`:'')+
                (otherLangs.length?`<table class="ep-lang"><tr><th class="ep-col0" rowspan="2">Other language(s)</th><th colspan="2">Understanding</th><th colspan="2">Speaking</th><th rowspan="2">Writing</th></tr><tr><th class="ep-sub">Listening</th><th class="ep-sub">Reading</th><th class="ep-sub">Spoken interaction</th><th class="ep-sub">Spoken production</th></tr>${otherLangs.map(l=>`<tr><td class="ep-col0">${esc(l.language)}</td><td>${epLvl(l)}</td><td>${epLvl(l)}</td><td>${epLvl(l)}</td><td>${epLvl(l)}</td><td>${epLvl(l)}</td></tr>`).join('')}</table><div class="ep-legend">Levels: A1/A2: Basic user - B1/B2: Independent user - C1/C2: Proficient user. <a href="https://europa.eu/europass/en/common-european-framework-reference-languages" target="_blank" rel="noopener">Common European Framework of Reference for Languages</a></div>`:'')+
                epSkillRow('Communication skills',epB.comm)+
                epSkillRow('Organisational / managerial skills',epB.org)+
                epSkillRow('Job-related skills',epB.job)+
                epSkillRow('Digital competence',epB.dig):''}
            <div class="ep-footer">© European Union, 2002-2015 | <a href="https://europass.cedefop.europa.eu" target="_blank" rel="noopener">europass.cedefop.europa.eu</a></div>`;
            break;}
        case'tech':{
            /* Jake's Resume — the de-facto software-engineer standard (r/EngineeringResumes):
               monochrome, bold ruled section headings, right-aligned dates, pipe-separated contact. */
            const techLinks=[email,phone,linkedin,location].filter(Boolean);
            const techItem=e=>`<div class="cv-item"><div class="cv-item-header"><span>${esc(e.title)}${e.company?` · ${esc(e.company)}`:''}</span><span>${esc(e.dates)}</span></div><p>${esc(e.description)}</p></div>`;
            const techEdu=e=>`<div class="cv-item"><div class="cv-item-header"><span>${esc(e.degree)}${e.institution?` · ${esc(e.institution)}`:''}</span><span>${esc(e.year)}</span></div></div>`;
            html=`${ph?`<div style="text-align:center;margin-bottom:2mm">${ph}</div>`:''}<div class="cv-tech-name">${esc(name)}</div>${title?`<div class="cv-tech-title">${esc(title)}</div>`:''}${techLinks.length?`<div class="cv-tech-contact">${techLinks.map(esc).join(' | ')}</div>`:''}${summary.trim()?`<div class="cv-section cv-tech-sec"><h2>Summary</h2><p>${esc(summary)}</p></div>`:''}${skillList.length?`<div class="cv-section cv-tech-sec"><h2>Skills</h2><p class="cv-tech-skills">${skillList.map(esc).join(' · ')}</p></div>`:''}${exp.length?`<div class="cv-section cv-tech-sec"><h2>Experience</h2>${exp.map(techItem).join('')}</div>`:''}${edu.length?`<div class="cv-section cv-tech-sec"><h2>Education</h2>${edu.map(techEdu).join('')}</div>`:''}${langLines?`<div class="cv-section cv-tech-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'harvard':{
            /* Education-first classic (career-services format) — degrees lead, double-rule contact,
               small-caps centred section headings with a short accent underline. */
            const hvEdu=e=>`<div class="cv-item"><div class="cv-item-header"><span>${esc(e.degree)}</span><span>${esc(e.year)}</span></div><div class="cv-item-sub">${esc(e.institution)}</div></div>`;
            const hvExp=e=>`<div class="cv-item"><div class="cv-item-header"><span>${esc(e.title)}</span><span>${esc(e.dates)}</span></div><div class="cv-item-sub">${esc(e.company)}</div><p>${esc(e.description)}</p></div>`;
            html=`${ph?`<div style="text-align:center;margin-bottom:2mm">${ph}</div>`:''}<div class="cv-name">${esc(name)}</div>${cs?`<div class="cv-hv-contact">${esc(cs)}</div>`:''}${edu.length?`<div class="cv-section cv-hv-sec"><h2>Education</h2>${edu.map(hvEdu).join('')}</div>`:''}${summary.trim()?`<div class="cv-section cv-hv-sec"><h2>Objective</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section cv-hv-sec"><h2>Experience</h2>${exp.map(hvExp).join('')}</div>`:''}${skills.trim()?`<div class="cv-section cv-hv-sec"><h2>Skills</h2><p>${esc(skills)}</p></div>`:''}${langLines?`<div class="cv-section cv-hv-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'cascade':{
            /* Cascade — the popular two-column sidebar design: tinted left rail for contact,
               skills and languages; accent-ruled header and main column on the right. */
            const cascSkill=skillList.length?`<div class="cv-section"><h2>Skills</h2>${skillList.map(s=>`<div class="cv-casc-skill">${esc(s)}</div>`).join('')}</div>`:'';
            const cascLang=langs.length?`<div class="cv-section"><h2>Languages</h2>${langs.map(l=>`<div class="cv-lang-line"><span>${esc(l.language)}</span><span class="lvl">${esc(l.level||'')}</span></div>`).join('')}</div>`:'';
            html=`<div class="cv-casc"><aside class="cv-casc-side">${ph?`<div class="cv-casc-photo">${ph}</div>`:''}${cs?`<div class="cv-section"><h2>Contact</h2><p>${esc(cs).replace(/\|/g,'<br>')}</p></div>`:''}${cascSkill}${cascLang}</aside><div class="cv-casc-main"><div class="cv-casc-head"><div class="cv-name">${esc(name)}</div>${title?`<div class="cv-title">${esc(title)}</div>`:''}</div>${summary.trim()?`<div class="cv-section"><h2>Profile</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section"><h2>Education</h2>${dH}</div>`:''}</div></div>`;
            break;}
        case'functional':{
            /* Functional / skills-first — core-competency chips lead the page, experience follows
               in compact rows: the recommended shape for career changes and portfolio careers. */
            const fnChips=skillList.length?`<div class="cv-section cv-fn-sec"><h2>Core Competencies</h2><div class="cv-fn-chips">${skillList.map(s=>`<span class="cv-fn-chip">${esc(s)}</span>`).join('')}</div></div>`:'';
            const fnExp=e=>`<div class="cv-item"><div class="cv-item-header"><span>${esc(e.title)}${e.company?` — ${esc(e.company)}`:''}</span><span>${esc(e.dates)}</span></div><p>${esc(e.description)}</p></div>`;
            html=`<div class="cv-fn-head">${ph}<div style="min-width:0"><div class="cv-name">${esc(name)}</div>${title?`<div class="cv-title">${esc(title)}</div>`:''}${cs?`<div class="cv-fn-contact">${esc(cs)}</div>`:''}</div></div>${fnChips}${summary.trim()?`<div class="cv-section cv-fn-sec"><h2>Professional Summary</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section cv-fn-sec"><h2>Experience</h2>${exp.map(fnExp).join('')}</div>`:''}${edu.length?`<div class="cv-section cv-fn-sec"><h2>Education</h2>${dH}</div>`:''}${langLines?`<div class="cv-section cv-fn-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'pastel':{
            /* Pastel — soft tinted header band and pill-shaped accents; airy and friendly,
               one of the most-picked designs on the big resume-builder sites. */
            html=`<div class="cv-pastel-band"><div style="display:flex;align-items:center;gap:4mm">${ph}<div style="min-width:0"><div class="cv-name">${esc(name)}</div>${title?`<div class="cv-pastel-title">${esc(title)}</div>`:''}${cs?`<div class="cv-pastel-contact">${esc(cs)}</div>`:''}</div></div></div>${summary.trim()?`<div class="cv-section cv-pastel-sec"><h2>About Me</h2><p>${esc(summary)}</p></div>`:''}${skillList.length?`<div class="cv-section cv-pastel-sec"><h2>Skills</h2><div class="cv-pastel-skills">${skillList.map(s=>`<span class="cv-pastel-skill">${esc(s)}</span>`).join('')}</div></div>`:''}${exp.length?`<div class="cv-section cv-pastel-sec"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section cv-pastel-sec"><h2>Education</h2>${dH}</div>`:''}${langLines?`<div class="cv-section cv-pastel-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'vogue':{
            /* Vogue — high-fashion editorial: oversized italic masthead, double rules,
               letterspaced small-cap contact line. */
            const vgExp=e=>`<div class="cv-item"><div class="cv-item-header"><span>${esc(e.title)}</span><span>${esc(e.dates)}</span></div><div class="cv-vg-org">${esc(e.company)}</div><p>${esc(e.description)}</p></div>`;
            html=`${ph?`<div style="text-align:center;margin-bottom:2mm">${ph}</div>`:''}<div class="cv-vg-name">${esc(name)}</div>${title?`<div class="cv-vg-tag">${esc(title)}</div>`:''}<div class="cv-vg-rule"></div>${cs?`<div class="cv-vg-contact">${esc(cs)}</div>`:''}<div class="cv-vg-rule thin"></div>${summary.trim()?`<div class="cv-section cv-vg-sec"><h2>Profile</h2><p>${esc(summary)}</p></div>`:''}${skillList.length?`<div class="cv-section cv-vg-sec"><h2>Expertise</h2><p style="letter-spacing:0.04em">${skillList.map(esc).join(' · ')}</p></div>`:''}${exp.length?`<div class="cv-section cv-vg-sec"><h2>Experience</h2>${exp.map(vgExp).join('')}</div>`:''}${edu.length?`<div class="cv-section cv-vg-sec"><h2>Education</h2>${dH}</div>`:''}${langLines?`<div class="cv-section cv-vg-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'primo':{
            /* Primo — the popular iconed-sidebar design (after Zety's Primo): tinted rail
               with round initial chips for contact and skill bars, square-marker
               headings in the main column. v2.10: bar widths follow the 1–5 skill
               sliders; untrained skills fall back to a deterministic hash. */
            const prHash=s=>{let h=0;for(const c of String(s))h=(h*31+c.charCodeAt(0))>>>0;return 55+h%41;};
            /* v2.10: skill bars follow the 1–5 sliders (level × 20%), falling
               back to the deterministic hash only when no level is set. */
            const prSkillPct=s=>{const v=D.skillLv&&D.skillLv[s];return v?Math.min(100,Math.max(10,v*20)):prHash(s);};
            const prLvlPct={'Native':100,'C2':90,'C1':80,'B2':70,'B1':60,'A2':45,'A1':30};
            const prCt=[['Email',email],['Phone',phone],['LinkedIn',linkedin],['Location',location]].filter(x=>x[1]);
            const prBarRow=(label,pct)=>`<div class="cv-primo-skill"><span class="cv-primo-skill-name">${esc(label)}</span><span class="cv-primo-track"><span class="cv-primo-fill" style="width:${pct}%"></span></span></div>`;
            html=`<div class="cv-primo"><aside class="cv-primo-side">${ph?`<div class="cv-primo-photo">${ph}</div>`:''}${prCt.length?`<div class="cv-primo-box"><h2>Contact</h2>${prCt.map(x=>`<div class="cv-primo-ct"><span class="cv-primo-dot">${esc(x[0].charAt(0))}</span><span>${esc(x[1])}</span></div>`).join('')}</div>`:''}${skillList.length?`<div class="cv-primo-box"><h2>Skills</h2>${skillList.slice(0,12).map(s=>prBarRow(s,prSkillPct(s))).join('')}</div>`:''}${langs.length?`<div class="cv-primo-box"><h2>Languages</h2>${langs.map(l=>prBarRow(l.language,l.level?(prLvlPct[l.level]||55):prHash(l.language))).join('')}</div>`:''}</aside><div class="cv-primo-main"><div class="cv-primo-head"><div class="cv-name">${esc(name)}</div>${title?`<div class="cv-title">${esc(title)}</div>`:''}</div>${summary.trim()?`<div class="cv-section cv-primo-sec"><h2>Profile</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section cv-primo-sec"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section cv-primo-sec"><h2>Education</h2>${dH}</div>`:''}</div></div>`;
            break;}
        case'diamond':{
            /* Diamond — centered, decoratively framed headings (after Zety's Diamond):
             * name mid-page, diamond-flanked section titles, airy single column. */
            html=`${ph?`<div style="text-align:center;margin-bottom:2mm">${ph}</div>`:''}<div class="cv-name">${esc(name)}</div>${title?`<div class="cv-dm-title">${esc(title)}</div>`:''}${cs?`<div class="cv-dm-contact">${esc(cs)}</div>`:''}<div class="cv-dm-divider"></div>${summary.trim()?`<div class="cv-section cv-dm-sec"><h2>Summary</h2><p>${esc(summary)}</p></div>`:''}${skillList.length?`<div class="cv-section cv-dm-sec"><h2>Skills</h2><p>${skillList.map(esc).join(' · ')}</p></div>`:''}${exp.length?`<div class="cv-section cv-dm-sec"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section cv-dm-sec"><h2>Education</h2>${dH}</div>`:''}${langLines?`<div class="cv-section cv-dm-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'berlin':{
            /* Berlin — the minimalist header-band look (Novoresume's Simple family):
             * ink-black masthead, hairline-ruled uppercase headings, generous whitespace. */
            html=`<div class="cv-bln-band"><div class="cv-bln-id">${ph?`<div class="cv-bln-photo">${ph}</div>`:''}<div style="min-width:0"><div class="cv-bln-name">${esc(name)}</div>${title?`<div class="cv-bln-title">${esc(title)}</div>`:''}</div></div>${cs?`<div class="cv-bln-contact">${esc(cs)}</div>`:''}</div>${summary.trim()?`<div class="cv-section cv-bln-sec"><h2>Profile</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section cv-bln-sec"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section cv-bln-sec"><h2>Education</h2>${dH}</div>`:''}${skillList.length?`<div class="cv-section cv-bln-sec"><h2>Skills</h2><p>${skillList.map(esc).join(' · ')}</p></div>`:''}${langLines?`<div class="cv-section cv-bln-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'monogram':{
            /* Monogram — initials badge beside the name (the "Initials" design family):
             * a confident colour square, letterspaced headings, airy single column. */
            const mgInitials=String(name||'').split(/\s+/).filter(Boolean).slice(0,2).map(w=>w.charAt(0).toUpperCase()).join('')||'CV';
            html=`<div class="cv-mono-head"><div class="cv-mono-badge">${esc(mgInitials)}</div><div style="min-width:0"><div class="cv-name">${esc(name)}</div>${title?`<div class="cv-title">${esc(title)}</div>`:''}${cs?`<div class="cv-mono-contact">${esc(cs)}</div>`:''}</div></div>${summary.trim()?`<div class="cv-section cv-mono-sec"><h2>Profile</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section cv-mono-sec"><h2>Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section cv-mono-sec"><h2>Education</h2>${dH}</div>`:''}${skillList.length?`<div class="cv-section cv-mono-sec"><h2>Skills</h2><div class="cv-mono-skills">${skillList.map(s=>`<span class="cv-mono-skill">${esc(s)}</span>`).join('')}</div></div>`:''}${langLines?`<div class="cv-section cv-mono-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'wallstreet':{
            /* Wall Street — finance-grade conservatism: serif throughout, double rules,
             * small-caps headings, nothing decorative. The investment-banking standard. */
            html=`${ph?`<div style="text-align:center;margin-bottom:2mm">${ph}</div>`:''}<div class="cv-ws-name">${esc(name)}</div><div class="cv-ws-cv">Curriculum Vitae</div>${cs?`<div class="cv-ws-contact">${esc(cs)}</div>`:''}${summary.trim()?`<div class="cv-section cv-ws-sec"><h2>Professional Summary</h2><p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section cv-ws-sec"><h2>Professional Experience</h2>${eH}</div>`:''}${edu.length?`<div class="cv-section cv-ws-sec"><h2>Education</h2>${dH}</div>`:''}${skills.trim()?`<div class="cv-section cv-ws-sec"><h2>Skills</h2><p>${esc(skills)}</p></div>`:''}${langLines?`<div class="cv-section cv-ws-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'medic':{
            /* Medic — clinical-clean healthcare style: scannable labeled contact grid,
             * date pills, left-accent section headings. Built for high-volume screening. */
            const mdCt=[['Email',email],['Phone',phone],['LinkedIn',linkedin],['Location',location]].filter(x=>x[1]);
            const mdExp=e=>`<div class="cv-item"><div class="cv-item-header"><span>${esc(e.title)}${e.company?` — ${esc(e.company)}`:''}</span><span class="cv-md-date">${esc(e.dates)}</span></div><p>${esc(e.description)}</p></div>`;
            const mdEdu=e=>`<div class="cv-item"><div class="cv-item-header"><span>${esc(e.degree)}${e.institution?` — ${esc(e.institution)}`:''}</span><span class="cv-md-date">${esc(e.year)}</span></div></div>`;
            html=`<div class="cv-md-head">${ph}<div style="min-width:0"><div class="cv-name">${esc(name)}</div>${title?`<div class="cv-title">${esc(title)}</div>`:''}</div></div>${mdCt.length?`<div class="cv-md-grid">${mdCt.map(x=>`<div class="cv-md-cell"><span class="cv-md-label">${esc(x[0])}</span><span>${esc(x[1])}</span></div>`).join('')}</div>`:''}${summary.trim()?`<div class="cv-section cv-md-sec"><h2>Professional Summary</h2><p>${esc(summary)}</p></div>`:''}${skillList.length?`<div class="cv-section cv-md-sec"><h2>Clinical &amp; Technical Skills</h2><p>${skillList.map(esc).join(' · ')}</p></div>`:''}${exp.length?`<div class="cv-section cv-md-sec"><h2>Experience</h2>${exp.map(mdExp).join('')}</div>`:''}${edu.length?`<div class="cv-section cv-md-sec"><h2>Education &amp; Licensure</h2>${edu.map(mdEdu).join('')}</div>`:''}${langLines?`<div class="cv-section cv-md-sec"><h2>Languages</h2>${langLines}</div>`:''}`;
            break;}
        case'scholar':{
            /* Scholar — an exact recreation of the reference CV (the modern
               Europass editor design): full-bleed navy #003399 masthead with
               the official Europass logo, a letter-spaced CURRICULUM VITAE
               eyebrow, IBM Plex Sans typography, letter-spaced #1a3fa0 caps
               section headers over thin #003399 rules, the grey Personal
               Information block with underlined values, publication entries
               with venue/status/DOI lines, and 5-square proficiency ratings
               for skills and languages — skill squares come from the 1–5
               sliders in the Skills form (default 4), language levels map
               Native/C2=5 down to A1=2. */
            const scHash=x=>{let h=0;for(const c of String(x))h=(h*31+c.charCodeAt(0))>>>0;return h;};
            const scLvlN={'Native':5,'C2':5,'C1':4,'B2':3,'B1':3,'A2':2,'A1':2};
            /* v2.10: skill squares follow the 1–5 sliders in the Skills form
               (default 4 until the user adjusts); language squares follow the
               CEFR level select. A1 renders 2 squares, matching the reference CV. */
            const scSkillN=s=>{const v=D.skillLv&&D.skillLv[s];return v?Math.min(5,Math.max(1,v)):4;};
            const scSq=n=>Array.from({length:5},(_,i)=>`<span class="cv-sch-sq${i<n?' on':''}"></span>`).join('');
            const scCt=[['Address',location],['Telephone',phone],['Email',email],['Web',linkedin]].filter(x=>x[1]);
            const scH=t=>`<h2>${t}</h2>`;
            const scExp=e=>`<div class="cv-sch-item"><div class="cv-sch-row"><span class="cv-sch-t">${esc(e.company||e.title)}</span>${e.dates?`<span class="cv-sch-date">${esc(e.dates)}</span>`:''}</div>${e.company&&e.title?`<div class="cv-sch-sub">${esc(e.title)}</div>`:''}${e.description?`<p>${esc(e.description)}</p>`:''}</div>`;
            const scEdu=e=>`<div class="cv-sch-item"><div class="cv-sch-row"><span class="cv-sch-t">${esc(e.institution||e.degree)}</span>${e.year?`<span class="cv-sch-date">${esc(e.year)}</span>`:''}</div>${e.institution&&e.degree?`<div class="cv-sch-sub">${esc(e.degree)}</div>`:''}</div>`;
            const scPub=p=>`<div class="cv-sch-item"><div class="cv-sch-row"><span class="cv-sch-t">${esc(p.title)}</span>${p.dates?`<span class="cv-sch-date">${esc(p.dates)}</span>`:''}</div>${p.venue?`<div class="cv-sch-sub">${esc(p.venue)}</div>`:''}${p.status?`<div class="cv-sch-sub cv-sch-sub2">${esc(p.status)}</div>`:''}${p.link?`<a class="cv-sch-link" href="${esc(p.link)}" target="_blank" rel="noopener">DOI: ${esc(p.link)}</a>`:''}</div>`;
            const scProj=p=>`<div class="cv-sch-item"><div class="cv-sch-row"><span class="cv-sch-t">${esc(p.name)}</span></div>${p.description?`<div class="cv-sch-sub">${esc(p.description)}</div>`:''}${p.link?`<a class="cv-sch-link" href="${esc(p.link)}" target="_blank" rel="noopener">${esc(p.link)}</a>`:''}</div>`;
            const scVol=v=>`<div class="cv-sch-item"><div class="cv-sch-row"><span class="cv-sch-t">${esc(v.organization||v.role)}</span></div>${v.organization&&v.role?`<div class="cv-sch-sub">${esc(v.role)}</div>`:''}${v.description?`<p>${esc(v.description)}</p>`:''}</div>`;
            html=`<div class="cv-sch-band"><div class="cv-sch-id"><img class="cv-sch-logo" src="${EP_LOGO_MODERN}" alt="Europass"><div class="cv-sch-eyebrow">Curriculum Vitae</div><div class="cv-sch-name">${esc(name)}</div>${title?`<div class="cv-sch-tag">${esc(title)}</div>`:''}</div>${ph?`<div class="cv-sch-photo">${ph}</div>`:''}</div>${scCt.length?`<div class="cv-sch-pi">${scH('Personal Information')}<div class="cv-sch-pi-grid">${scCt.map(x=>`<div class="cv-sch-pair"><span class="cv-sch-label">${esc(x[0])}</span><span class="cv-sch-val">${esc(x[1])}</span></div>`).join('')}</div></div>`:''}<div class="cv-sch-body">${summary.trim()?`<div class="cv-section cv-sch-sec">${scH('Summary')}<p>${esc(summary)}</p></div>`:''}${exp.length?`<div class="cv-section cv-sch-sec">${scH('Experience')}${exp.map(scExp).join('')}</div>`:''}${edu.length?`<div class="cv-section cv-sch-sec">${scH('Education')}${edu.map(scEdu).join('')}</div>`:''}${pubs.length?`<div class="cv-section cv-sch-sec">${scH('Publications')}${pubs.map(scPub).join('')}</div>`:''}${projs.length?`<div class="cv-section cv-sch-sec">${scH('Projects')}${projs.map(scProj).join('')}</div>`:''}${vols.length?`<div class="cv-section cv-sch-sec">${scH('Volunteering')}${vols.map(scVol).join('')}</div>`:''}${skillList.length?`<div class="cv-section cv-sch-sec">${scH('Skills')}<div class="cv-sch-grid cv-sch-grid3">${skillList.map(sk=>`<div class="cv-sch-skill"><span class="cv-sch-t">${esc(sk)}</span><span class="cv-sch-sqs">${scSq(scSkillN(sk))}</span></div>`).join('')}</div></div>`:''}${interests.trim()?`<div class="cv-section cv-sch-sec">${scH('Interests')}<div class="cv-sch-int">${esc(interests)}</div></div>`:''}${langs.length?`<div class="cv-section cv-sch-sec">${scH('Languages')}<div class="cv-sch-grid cv-sch-grid4">${langs.map(l=>`<div class="cv-sch-skill"><span class="cv-sch-t">${esc(l.language)}</span>${l.level?`<span class="cv-sch-sub">${esc(l.level)}</span>`:''}<span class="cv-sch-sqs">${scSq(l.level?(scLvlN[l.level]||3):(1+scHash(l.language)%4))}</span></div>`).join('')}</div></div>`:''}</div>`;
            break;}
        default:html=`<div class="cv-name">${esc(name)}</div><p>${esc(title)} | ${esc(cs)}</p>${orderedContent}`;
    }
    return html;
}
